'use strict';
// Nightly. Writes exports/agent-ratings-weekly.json: for each agent, the ratings their tickets received in the past
// seven days (a rating exactly seven days old still counts) and the average score to two decimals. Tickets with no
// owner are skipped. Separate from tickets.json, which finance reads.
const fs = require('node:fs');
const path = require('node:path');
const { ownerOf } = require('../tickets');

const WINDOW_DAYS = 7;
const DAY = 24 * 60 * 60 * 1000;
const EXPORT_DIR = path.join(__dirname, '..', '..', 'exports');

function weeklyRatingSummary(store, { now = new Date(), dir = EXPORT_DIR } = {}) {
  const since = now.getTime() - WINDOW_DAYS * DAY;
  const byAgent = new Map();
  for (const t of store.listTickets()) {
    const owner = ownerOf(t);
    if (t.rating_score == null || owner == null) continue;
    if (new Date(t.rated_at).getTime() < since) continue;
    const acc = byAgent.get(owner) || { sum: 0, count: 0 };
    acc.sum += t.rating_score;
    acc.count += 1;
    byAgent.set(owner, acc);
  }
  const rows = [...byAgent.entries()]
    .sort(([a], [b]) => a - b)
    .map(([agent_id, { sum, count }]) => ({ agent_id, ratings: count, average: Math.round((sum / count) * 100) / 100 }));
  fs.mkdirSync(dir, { recursive: true });
  const file = path.join(dir, 'agent-ratings-weekly.json');
  fs.writeFileSync(file, JSON.stringify(rows, null, 2) + '\n');
  return { file, rows: rows.length };
}

module.exports = { weeklyRatingSummary, WINDOW_DAYS };
```
